"use strict";function csatLabel(e){switch(e){case 1:return TKA.t("modal_40_rating_1","Muy insatisfecho");case 2:return TKA.t("modal_40_rating_2","Insatisfecho");case 3:return TKA.t("modal_40_rating_3","Neutral");case 4:return TKA.t("modal_40_rating_4","Satisfecho");case 5:return TKA.t("modal_40_rating_5","Muy satisfecho");default:return""}}function csatStars(e){for(var s="",t=1;t<=5;t++)s+='<i class="fa-solid fa-star tkt-csat-star'+(t<=e?" on":"")+'"></i>';return s}function openCsatModal(e){var s=openModal(modalShell({icon:"fa-regular fa-face-smile",kicker:TKA.t("kicker_ticket_satisfaction","Ticket \xB7 satisfacci\xF3n"),titleChip:e.ticket_number,title:TKA.t("modal_title_csat_survey","Encuesta CSAT"),width:"sm",body:'<div class="tkt-empty-box">'+TKA.t("loading","Cargando\u2026")+"</div>",foot:'<button type="button" class="tkt-btn" data-modal-close>'+TKA.t("close","Cerrar")+"</button>"}));$.getJSON(e.url_csat).done(function(t){var a=t&&t.csat;if(!a){s.find(".tkt-modal-body").html('<div class="tkt-empty-box">'+TKA.t("modal_40_load_failed","No se pudo cargar la valoraci\xF3n.")+"</div>");return}var n;a.rating?n='<div class="tkt-cap">'+TKA.t("modal_40_customer_response_caption","Respuesta del cliente")+'</div><div class="tkt-csat-head"><span class="tkt-csat-score">'+a.rating+'</span><span class="tkt-csat-main"><span class="tkt-csat-stars">'+csatStars(a.rating)+'</span><span class="tkt-csat-label">'+escapeHtml(csatLabel(a.rating))+(a.rated_at_human?TKA.t("modal_40_answered_on_prefix"," \xB7 respondida el ")+escapeHtml(a.rated_at_human):"")+"</span></span></div>"+(a.comment?'<blockquote class="tkt-form-quote">'+escapeHtml(a.comment)+"</blockquote>":"")+(a.reason?'<div class="tkt-kv"><span class="k">'+TKA.t("modal_40_reason_label","Motivo")+'</span><span class="v">'+escapeHtml(a.reason)+"</span></div>":""):n='<div class="tkt-empty-box">'+TKA.t("modal_40_no_rating_yet","Este ticket todav\xEDa no tiene valoraci\xF3n.")+"</div>"+(a.can_resend?'<button type="button" class="tkt-btn tkt-w-100" id="tkt-csat-resend">'+TKA.t("btn_resend_csat_survey","Reenviar encuesta de satisfacci\xF3n")+"</button>":""),n+='<div class="tkt-kv-grid tkt-csat-meta"><span>'+TKA.t("modal_40_agent_label","agente")+"</span><span>"+escapeHtml(a.agent||"\u2014")+"</span><span>"+TKA.t("modal_40_resolution_time_label","tiempo de resoluci\xF3n")+"</span><span>"+escapeHtml(a.resolution_human||"\u2014")+"</span><span>"+TKA.t("modal_40_reopenings_label","reaperturas")+"</span><span>"+a.reopenings+"</span><span>"+TKA.t("modal_40_agent_average_label","media del agente")+"</span><span>"+(a.agent_average!==null?TKA.t("modal_40_agent_average_value",":n / 5",{":n":a.agent_average}):TKA.t("modal_40_no_ratings_value","sin valoraciones"))+"</span></div>",s.find(".tkt-modal-body").html(n)}).fail(function(){s.find(".tkt-modal-body").html('<div class="tkt-empty-box">'+TKA.t("modal_40_load_failed","No se pudo cargar la valoraci\xF3n.")+"</div>")}),s.on("click","#tkt-csat-resend",function(){var t=$(this).prop("disabled",!0).text(TKA.t("btn_sending","Enviando\u2026"));$.ajax({url:e.url_send_csat,method:"POST",headers:{Accept:"application/json"}}).done(function(a){window.toastr&&toastr.success(a&&a.message||TKA.t("survey_resent","Encuesta reenviada.")),closeModal()}).fail(function(a){var n=apiErrorMessage(a,TKA.t("modal_40_resend_failed","No se pudo reenviar la encuesta."));tktNotify("error",n),t.prop("disabled",!1).text(TKA.t("btn_resend_csat_survey","Reenviar encuesta de satisfacci\xF3n"))})})}
